-- Integration-local facts and explicit per-kind commands; existing repository/commit contracts unchanged.
CREATE TABLE github_work_sync_state(repository_id uuid NOT NULL REFERENCES github_repository(repository_id),kind text NOT NULL CHECK(kind IN ('ISSUE','PULL_REQUEST')),version bigint NOT NULL CHECK(version>0),observed_at timestamptz NOT NULL,PRIMARY KEY(repository_id,kind));
CREATE TABLE github_work_item(item_id uuid PRIMARY KEY,space_id uuid NOT NULL,repository_id uuid NOT NULL REFERENCES github_repository(repository_id),kind text NOT NULL CHECK(kind IN ('ISSUE','PULL_REQUEST')),number bigint NOT NULL CHECK(number BETWEEN 1 AND 9007199254740991),external_id text NOT NULL CHECK(external_id ~ '^[1-9][0-9]{0,18}$'),state text NOT NULL CHECK(state IN ('OPEN','CLOSED')),version bigint NOT NULL CHECK(version>0),snapshot jsonb NOT NULL,UNIQUE(repository_id,number),UNIQUE(repository_id,external_id));
CREATE INDEX github_work_catalog ON github_work_item(space_id,repository_id,kind,state,item_id);
CREATE TABLE github_work_item_revision(revision_id uuid PRIMARY KEY,item_id uuid NOT NULL REFERENCES github_work_item(item_id),version bigint NOT NULL CHECK(version>0),actor_id uuid NOT NULL,occurred_at timestamptz NOT NULL,snapshot jsonb NOT NULL,UNIQUE(item_id,version));
CREATE TABLE github_work_receipt(sync_id uuid PRIMARY KEY,space_id uuid NOT NULL,repository_id uuid NOT NULL REFERENCES github_repository(repository_id),kind text NOT NULL CHECK(kind IN ('ISSUE','PULL_REQUEST')),actor_id uuid NOT NULL,request_key text NOT NULL CHECK(request_key ~ '^[0-9a-f]{32}$'),expected_version bigint NOT NULL CHECK(expected_version>=0),sync_version bigint NOT NULL CHECK(sync_version>0),snapshot jsonb NOT NULL,UNIQUE(repository_id,kind,actor_id,request_key),UNIQUE(repository_id,kind,sync_version));
